package com.pet.buscaativa;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import com.pet.buscaativa.entities.*;
import com.pet.buscaativa.entities.dto.*;
import com.pet.buscaativa.entities.enums.*;
import com.pet.buscaativa.services.*;
import com.pet.buscaativa.repositories.*;

class CancellationSecurityAuditTests extends CancellationRegularizationSupport {
    @MockitoSpyBean AuditoriaRegularizacaoService audit;
    @MockitoSpyBean HistoricoPacienteService historyWriter;
    @Autowired UsfReferenciaRepository usfs;
    @ParameterizedTest @CsvSource({"recover,missing_version","fact,missing_version","recover,negative_version","fact,negative_version","recover,missing_reason","fact,missing_reason","recover,blank","fact,blank","recover,short","fact,short","recover,generic","fact,generic","recover,long","fact,long"})
    void rr16Rf22VersionAndReasonAreMandatory(String op,String defect) throws Exception {var a=canceled(op.equals("recover"));var body=new HashMap<String,Object>();body.put("version",a.getVersion());body.put("justificativa",REASON);if(op.equals("fact"))body.put("novaFrequencia","PRESENTE");switch(defect){case "missing_version"->body.remove("version");case "negative_version"->body.put("version",-1);case "missing_reason"->body.remove("justificativa");case "blank"->body.put("justificativa"," ");case "short"->body.put("justificativa","curto");case "generic"->body.put("justificativa","não informado");case "long"->body.put("justificativa","x".repeat(2001));default->throw new IllegalArgumentException();}var before=database();assertEquals(422,request(admin,a,op.equals("fact")?"frequencia":"recuperar-reserva",body).getStatus());assertEquals(before,database());}
    @ParameterizedTest @ValueSource(strings={"NAO_REGISTRADA","AGENDADO","REMARCADO","CANCELADO","SUBSTITUIDA"})
    void invalidFactualDestinationNeverBecomesAnOperationalCommand(String f) throws Exception {var a=canceled(false);var before=database();var r=factual(admin,a,Map.of("novaFrequencia",f,"version",a.getVersion(),"justificativa",REASON));assertEquals(f.equals("NAO_REGISTRADA")?422:400,r.getStatus());assertEquals(before,database());}
    @ParameterizedTest @ValueSource(strings={"recuperar-reserva","frequencia"})
    void unauthenticatedIs401AndDifferentUsfIs404(String operation) throws Exception {var pair=tx(()->{var x=new UsfReferencia();x.setCnes(UUID.randomUUID().toString());usfs.saveAndFlush(x);var y=new UsfReferencia();y.setCnes(UUID.randomUUID().toString());usfs.saveAndFlush(y);professional.setUnidadeAtuacao(UnidadeAtuacao.USF);professional.setUsfAtuacao(x);users.saveAndFlush(professional);patient.setCapsReferencia(null);patient.setUsfReferencia(x);patients.saveAndFlush(patient);var ext=user(TipoUsuario.ADMINISTRADOR,UnidadeAtuacao.USF);ext.setUsfAtuacao(y);users.saveAndFlush(ext);return ext;});var a=canceled(operation.equals("recuperar-reserva"));Object body=operation.equals("frequencia")?fact(a,FrequenciaAssistencial.PRESENTE):recovery(a);var before=database();assertEquals(401,mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/agendamentos/"+a.getId()+"/regularizacao-cancelamento/"+operation).contentType("application/json").content(json.writeValueAsString(body))).andReturn().getResponse().getStatus());assertEquals(404,request(pair,a,operation,body).getStatus());assertEquals(before,database());}
    @ParameterizedTest @ValueSource(strings={"owner","colleague","reception","foreign"})
    void directServicesCannotBypassOwnershipOrProfile(String role){var future=canceled(true);var past=canceled(false);var user=actor(role);SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(user,null,user.getAuthorities()));var before=database();if(role.equals("owner")){assertNotNull(service.recuperarReservaCancelada(future.getId(),recovery(future)));assertNotNull(service.regularizarFrequenciaCancelada(past.getId(),fact(past,FrequenciaAssistencial.PRESENTE)));}else{Class<? extends Exception> type=role.equals("foreign")?com.pet.buscaativa.services.exceptions.ResourceNotFoundException.class:org.springframework.security.access.AccessDeniedException.class;assertThrows(type,()->service.recuperarReservaCancelada(future.getId(),recovery(future)));assertThrows(type,()->service.regularizarFrequenciaCancelada(past.getId(),fact(past,FrequenciaAssistencial.PRESENTE)));assertEquals(before,database());}}
    @ParameterizedTest @CsvSource({"owner,200","admin,200","colleague,403","reception,403","foreign,404"})
    void authorizedPagedAuditSeparatesActorAndResponsible(String role,int expected) throws Exception {var a=canceled(false);assertEquals(200,factual(admin,a,fact(a,FrequenciaAssistencial.PRESENTE)).getStatus());var actor=actor(role);var r=mvc.perform(get("/api/agendamentos/"+a.getId()+"/regularizacoes-cancelamento").param("size","1").header("Authorization","Bearer "+tokens.gerarToken(actor))).andReturn().getResponse();assertEquals(expected,r.getStatus());if(expected==200){var n=json.readTree(r.getContentAsString()).get("content").get(0);assertEquals(admin.getIdPublico().toString(),n.get("usuarioId").asText());assertEquals(professional.getIdPublico().toString(),n.get("responsavelAtendimentoId").asText());assertEquals(REASON,n.get("justificativa").asText());assertEquals(clock.instant(),java.time.Instant.parse(n.get("ocorridoEm").asText()));}}
    @ParameterizedTest @CsvSource({"-1,20","0,0","0,101"})
    void auditPaginationDoesNotExposeUnboundedData(int page,int size) throws Exception {var a=canceled(false);assertEquals(422,mvc.perform(get("/api/agendamentos/"+a.getId()+"/regularizacoes-cancelamento").param("page",""+page).param("size",""+size).header("Authorization","Bearer "+tokens.gerarToken(admin))).andReturn().getResponse().getStatus());}
    @ParameterizedTest @ValueSource(strings={"recover_after_write","recover_after_audit","fact_after_write","fact_after_history","fact_after_audit"})
    void rr20Rf23Rf24Cs13To15RollbackAfterRealWrites(String point){var a=canceled(point.startsWith("recover"));var before=database();if(point.endsWith("audit"))doAnswer(i->{i.callRealMethod();assertTrue(regularizations.count()>0);throw new IllegalStateException("synthetic after audit INSERT");}).when(org.springframework.test.util.AopTestUtils.<AuditoriaRegularizacaoService>getUltimateTargetObject(audit)).registrar(any(),anyString(),anyString(),anyInt());else if(point.equals("recover_after_write"))doAnswer(i->{assertEquals("AGENDADA",jdbc.queryForObject("select situacao_reserva from tb_agendamento where id=?",String.class,a.getId()));throw new IllegalStateException("synthetic recovered row write");}).when(org.springframework.test.util.AopTestUtils.<AuditoriaRegularizacaoService>getUltimateTargetObject(audit)).registrar(any(),anyString(),anyString(),anyInt());else doAnswer(i->{if(point.equals("fact_after_history"))i.callRealMethod();assertEquals("PRESENTE",jdbc.queryForObject("select frequencia_assistencial from tb_agendamento where id=?",String.class,a.getId()));throw new IllegalStateException("synthetic factual write");}).when(historyWriter).registrarFatoRegularizado(any());authenticate();assertThrows(IllegalStateException.class,()->{if(point.startsWith("recover"))service.recuperarReservaCancelada(a.getId(),recovery(a));else service.regularizarFrequenciaCancelada(a.getId(),fact(a,FrequenciaAssistencial.PRESENTE));});assertEquals(before,database());}
    @Test void forgedFactualActorStateAndTimeAreIgnored() throws Exception {var a=canceled(false);var body=new HashMap<String,Object>();body.put("novaFrequencia","PRESENTE");body.put("version",a.getVersion());body.put("justificativa",REASON);body.put("atorId",colleague.getIdPublico());body.put("perfil","ADMINISTRADOR");body.put("unidade","CAPS_I");body.put("responsavelId",colleague.getIdPublico());body.put("ocorridoEm","1990-01-01T00:00:00Z");body.put("situacaoReserva","AGENDADA");assertEquals(200,factual(professional,a,body).getStatus());assertCanceledFact(a,FrequenciaAssistencial.PRESENTE);assertEquals(professional.getId(),jdbc.queryForObject("select ator_id from tb_auditoria_regularizacao_cancelamento where agendamento_id=?",Long.class,a.getId()));}
}
